              "title": "TEXTO",
              "content": "PROCEDIMENTO — INFILTRAÇÃO INTRA-ARTICULAR COM ÁCIDO HIALURÔNICO\n\nDIAGNÓSTICO E INDICAÇÃO: __________\n\nARTICULAÇÃO E LATERALIDADE: __________\n\nPRODUTO: __________\n\nCONCENTRAÇÃO E VOLUME: __________\n\nLOTE E VALIDADE: __________\n\nTÉCNICA E VIA DE ACESSO: __________\n\nANESTÉSICO UTILIZADO: __________\n\nREALIZADA ASSEPSIA E ANTISSEPSIA. PRODUTO ADMINISTRADO POR VIA INTRA-ARTICULAR CONFORME TÉCNICA E POSOLOGIA ESPECÍFICAS DO PRODUTO.\n\nINTERCORRÊNCIAS: __________\n\nORIENTAÇÕES\n\nREALIZAR REPOUSO RELATIVO DA ARTICULAÇÃO NAS PRIMEIRAS 24 A 48 HORAS.\n\nEVITAR ATIVIDADE FÍSICA INTENSA NO PERÍODO ORIENTADO.\n\nRETORNAR IMEDIATAMENTE EM CASO DE FEBRE, VERMELHIDÃO, CALOR LOCAL, EDEMA IMPORTANTE, DOR PROGRESSIVA OU DIFICULDADE ACENTUADA PARA MOVIMENTAR A ARTICULAÇÃO."
