              "content": "RELATÓRIO MÉDICO – INSS\n\nPACIENTE:\n\nFINALIDADE:\nRELATÓRIO MÉDICO PARA FINS DE AVALIAÇÃO JUNTO AO INSS/MÉDICO DO TRABALHO.\n\nHISTÓRIA CLÍNICA:\nPACIENTE EM ACOMPANHAMENTO ORTOPÉDICO, EM PÓS-OPERATÓRIO DE ____________________, REALIZADO EM ____/____/____, PARA TRATAMENTO DE ____________________. EVOLUI COM ____________________.\n\nDIAGNÓSTICO:\n____________________.\n\nCID-10:\n____________________.\n\nEXAMES COMPLEMENTARES:\nCONTROLE DE IMAGEM EVIDENCIANDO ____________________.\n\nEXAME FÍSICO:\nFERIDA OPERATÓRIA ____________________. APRESENTA DOR, EDEMA E LIMITAÇÃO DA AMPLITUDE DE MOVIMENTO DO MEMBRO OPERADO. EXAME NEUROVASCULAR DISTAL ____________________.\n\nTRATAMENTO:\nMANTIDO ACOMPANHAMENTO ORTOPÉDICO, CONTROLE DE IMAGEM E CUIDADOS PÓS-OPERATÓRIOS. FISIOTERAPIA MOTORA PARA ANALGESIA, GANHO DE AMPLITUDE DE MOVIMENTO, FORTALECIMENTO E REABILITAÇÃO FUNCIONAL COMPLETA.\n\nCONDIÇÃO FUNCIONAL E CAPACIDADE LABORAL:\nAPRESENTA LIMITAÇÃO FUNCIONAL TEMPORÁRIA DO MEMBRO OPERADO, COM RESTRIÇÃO PARA ____________________. NO MOMENTO, ENCONTRA-SE TEMPORARIAMENTE INCAPAZ PARA SUAS ATIVIDADES LABORAIS HABITUAIS.\n\nRECOMENDA-SE AFASTAMENTO POR ____________________, COM REAVALIAÇÃO CLÍNICA E RADIOGRÁFICA AO FINAL DO PERÍODO.\n\nDR. ROBSON MAGALHÃES DE MELO\nMÉDICO ORTOPEDISTA\nCRM-SP 165710 — TEOT 15301"
